wstrzykiwanie.opis:
Bez zmian w kodzie: aplikację startujemy z NODE_OPTIONS="--require /abs/flowlens.cjs" (CJS) lub NODE_OPTIONS="--import /abs/flowlens.mjs" (ESM). Preload ładuje się PRZED main, więc może zapiąć hooki modułów, subskrypcje diagnostics_channel i monkey-patche. Korelację (kor) i licznik (sek) trzymamy w AsyncLocalStorage: wejście (HTTP/job/wiadomość) robi als.run({kor,sek:0}, ...), a każde zdarzenie (in/out/sql/tx/log) czyta getStore(). Minimalny pomocnik (fd otwierany raz; writeSync na pliku z O_APPEND – krótkie linie w praktyce się nie przeplatają na lokalnym FS, ale nie na NFS; i tak zalecany plik per pid):

// flowlens.cjs
const fs=require('node:fs');const {AsyncLocalStorage}=require('node:async_hooks');const {threadId}=require('node:worker_threads');const {randomUUID}=require('node:crypto');
const als=new AsyncLocalStorage();
const fd=fs.openSync(process.env.FLOWLENS_FILE||`/tmp/flowlens-${process.pid}.jsonl`,'a');
let glob=0;
function emit(ev,f={}){const c=als.getStore();const r={ts:new Date().toISOString(),pid:process.pid,w:threadId,kor:c?c.kor:null,sek:c?++c.sek:++glob,ev,...f};try{fs.writeSync(fd,JSON.stringify(r,(k,v)=>typeof v==='bigint'?String(v):v)+'\n')}catch{}}
function run(kor,fn){return als.run({kor:kor||randomUUID(),sek:0},fn)}
module.exports={emit,run,als};globalThis.__flowlens=module.exports;

globalThis.__flowlens pozwala kodowi w ESM/bundlach i logpointom inspektora sięgnąć po ten sam singleton bez require. Moduły wbudowane (node:http, node:diagnostics_channel) są wspólne dla CJS i ESM, więc patch ich prototypów z preloadu CJS działa też w aplikacji ESM.
